import java.io.File;
import java.io.IOException;
import java.nio.file.Files;
import javax.servlet.http.HttpServlet;
import javax.servlet.http.HttpServletRequest;
import javax.servlet.http.HttpServletResponse;

public class SecureFileServlet extends HttpServlet {
    private static final String BASE_DIR = "/var/webapp/data";

    protected void doGet(HttpServletRequest request, HttpServletResponse response) throws IOException {
        String fileName = request.getParameter("file");

        // Basic validation: reject characters likely used in path traversal
        if (fileName != null && fileName.indexOf('/') == -1 && fileName.indexOf('\\') == -1) {
            File file = new File(BASE_DIR, fileName);

            // Canonicalize the path to resolve relative references like "../"
            String canonicalPath = file.getCanonicalPath();
            String canonicalBaseDir = new File(BASE_DIR).getCanonicalPath();

            // Ensure resolved path starts with the base directory
            if (canonicalPath.startsWith(canonicalBaseDir)) {
                response.setContentType("application/octet-stream");
                Files.copy(file.toPath(), response.getOutputStream());
            } else {
                response send error(HttpServletResponse.SC_FORBIDDEN, "Permission denied");
            }
        } else {
            response send error(HttpServletResponse.SC_BAD_REQUEST, "Invalid file name");
        }
    }
}
